import functools

def decorar(func):
    @functools.wraps(func)
    def envoltura(*args, **kwargs):
        # ... antes de la llamada
        resultado = func(*args, **kwargs)
        # ... después de la llamada
        return resultado
    return envoltura

@decorar
def saludar(nombre):
    return f"Hola, {nombre}"

import functools
import time

def cronometrar(func):
    @functools.wraps(func)
    def envoltura(*args, **kwargs):
        inicio = time.perf_counter()
        resultado = func(*args, **kwargs)
        duracion = time.perf_counter() - inicio
        print(f"{func.__name__}: {duracion:.4f} s")
        return resultado
    return envoltura

@cronometrar
def sumar_cuadrados(n):
    return sum(i * i for i in range(n))

print(sumar_cuadrados(200_000))
print(sumar_cuadrados.__name__)

import functools

def registrar(func):
    @functools.wraps(func)
    def envoltura(*args, **kwargs):
        print(f"-> {func.__name__}{args}")
        resultado = func(*args, **kwargs)
        print(f"<- {func.__name__} = {resultado}")
        return resultado
    return envoltura

def reintentar(veces):
    def decorador(func):
        @functools.wraps(func)
        def envoltura(*args, **kwargs):
            for intento in range(1, veces + 1):
                try:
                    return func(*args, **kwargs)
                except ValueError as error:
                    print(f"intento {intento} falló: {error}")
            raise RuntimeError(f"{func.__name__} falló {veces} veces")
        return envoltura
    return decorador

intentos = {"n": 0}

@registrar
@reintentar(3)
def descargar(url):
    intentos["n"] += 1
    if intentos["n"] < 3:
        raise ValueError("timeout")
    return f"datos de {url}"

print(descargar("api/ventas"))

