import functools

def contar_llamadas(func):
    @functools.wraps(func)
    def envoltura(*args, **kwargs):
        envoltura.llamadas += 1
        print(f"{func.__name__} llamada {envoltura.llamadas}")
        return func(*args, **kwargs)
    envoltura.llamadas = 0
    return envoltura

@contar_llamadas
def saludar(nombre):
    return f"Hola, {nombre}"

print(saludar("Ada"))
print(saludar("Linus"))
print("Total:", saludar.llamadas)

import functools

def repetir(veces):
    def decorador(func):
        @functools.wraps(func)
        def envoltura(*args, **kwargs):
            return [func(*args, **kwargs) for _ in range(veces)]
        return envoltura
    return decorador

@repetir(3)
def lanzar():
    return "ok"

@repetir(2)
def saludar(nombre):
    return f"Hola, {nombre}"

print(lanzar())
print(saludar("Ada"))
print(repetir(0)(lanzar)())

